A warm, low-contrast paper palette for daylight: cream background, ink-brown text, a muted terracotta accent, and a Cormorant serif clock. The search bar gets a soft lift on focus; everything else stays quiet.

```json
{
  "kind": "mnt.theme-pack",
  "packVersion": 2,
  "cssApiVersion": 1,
  "meta": {
    "name": "Warm Paper",
    "description": "Cream paper tones, ink-brown text and a serif clock, tuned for easy daytime reading.",
    "notes": "A plain linen, parchment or soft off-white texture wallpaper suits this theme best."
  },
  "theme": {
    "mode": "light",
    "colorLight": {
      "bg": "#f5efe4",
      "surface": "#fbf7ee",
      "text": "#332d26",
      "accent": "#a2543a"
    },
    "font": {
      "display": "cormorant",
      "ui": "system"
    },
    "radius": 10,
    "shadow": 18,
    "glass": 0,
    "density": "comfortable",
    "scale": 1,
    "iconShape": "rounded",
    "iconSize": 72
  },
  "background": {
    "type": "theme",
    "dim": 0
  },
  "css": ".mnt-clock {\n  letter-spacing: -0.01em;\n}\n.mnt-date {\n  color: var(--mnt-text-muted);\n}\n.mnt-search {\n  box-shadow: var(--mnt-elev-1);\n}\n.mnt-search:focus-within {\n  border-color: var(--mnt-accent);\n  box-shadow: var(--mnt-elev-2);\n}\n.mnt-link-icon {\n  box-shadow: 0 1px 2px rgba(51, 45, 38, 0.08);\n}\n.mnt-link:hover .mnt-link-icon {\n  box-shadow: 0 0 0 2px var(--mnt-accent-soft), 0 2px 6px rgba(51, 45, 38, 0.14);\n}\n.mnt-group-title .mnt-group-name {\n  color: var(--mnt-text-muted);\n}\n@media (prefers-reduced-motion: no-preference) {\n  .mnt-search,\n  .mnt-link-icon {\n    transition: box-shadow var(--mnt-dur-base) var(--mnt-ease), border-color var(--mnt-dur-base) var(--mnt-ease);\n  }\n}"
}
```

